import json
from datetime import datetime
from pathlib import Path

from mock_api import TRACE, search
from timezone_defaults import DEFAULT_TIMEZONE, MISSING_TZ_POLICY
from window_projection import wall_clock_pair


def validate_range(payload):
    """Return all locally detectable errors without making an API call."""
    errors = []
    if not isinstance(payload, dict):
        return [_error("query", "query must be an object", payload)]

    if "start_date" not in payload:
        errors.append(_error("start_date", "required", None))
    elif not isinstance(payload["start_date"], str):
        errors.append(_error("start_date", "timestamp must be a string", payload["start_date"]))

    if "end_date" in payload and not isinstance(payload["end_date"], str):
        errors.append(_error("end_date", "timestamp must be a string", payload["end_date"]))

    # Parse independently so a bad endpoint does not hide another bad endpoint.
    parsed = {}
    for name in ("start_date", "end_date"):
        if name not in payload or not isinstance(payload[name], str):
            continue
        try:
            parsed[name] = _parse_and_normalize(payload[name])
        except (TypeError, ValueError) as exc:
            errors.append(_error(name, f"invalid ISO 8601 timestamp: {exc}", payload[name]))

    if "start_date" not in parsed or "end_date" not in parsed:
        return errors

    start, end = parsed["start_date"], parsed["end_date"]
    start_utc = start.astimezone(DEFAULT_TIMEZONE)
    end_utc = end.astimezone(DEFAULT_TIMEZONE)
    normalized = {
        "start_date": start_utc.isoformat(),
        "end_date": end_utc.isoformat(),
        "timezone_policy": MISSING_TZ_POLICY,
    }

    # Equality is valid. Only an end instant before the start is invalid.
    if end_utc < start_utc:
        errors.append(_error(
            "date_range",
            "end_date must be greater than or equal to start_date after UTC normalization",
            payload,
            normalized,
        ))

    # Fall-back overlap policy: local clock ordering wins for a same-date,
    # repeated hour with distinct offsets, even where UTC ordering is valid.
    start_local, end_local = wall_clock_pair({"start": start, "end": end})
    if (
        start_local.date() == end_local.date()
        and start_local.hour == end_local.hour
        and start.utcoffset() != end.utcoffset()
        and end_local < start_local
    ):
        errors.append(_error(
            "date_range",
            "ambiguous fall-back DST range: end local clock is earlier than start local clock",
            payload,
            normalized,
        ))
    return errors


def _parse_and_normalize(value):
    parsed = datetime.fromisoformat(value)
    if parsed.tzinfo is None:
        # The migration policy is explicit: an omitted offset means UTC.
        parsed = parsed.replace(tzinfo=DEFAULT_TIMEZONE)
    return parsed


def _error(param, message, payload, normalized=None):
    result = {"param": param, "error": message, "payload": payload}
    if normalized is not None:
        result["normalized"] = normalized
    return result


def process_queries(path):
    TRACE.clear()
    payload = json.loads(Path(path).read_text(encoding="utf-8"))
    accepted = []
    rejected = []
    for index, query in enumerate(payload):
        errors = validate_range(query)
        if errors:
            rejected.append({"index": index, "errors": errors, "original": query})
            continue
        accepted.append(search(query))
    return {"accepted": accepted, "rejected": rejected, "trace": list(TRACE)}

